const reviews = $input.first().json.Reviews ?? $input.first().json.reviews ?? [];
const batchSize = 100;

const batches = [];

for (let i = 0; i < reviews.length; i += batchSize) {
  batches.push({
    json: {
      batch_number: Math.floor(i / batchSize) + 1,
      total_batches: Math.ceil(reviews.length / batchSize),
      reviews: reviews.slice(i, i + batchSize),
    },
  });
}

return batches;
